head.script:
scwin.gVar = {
    "cMaxByteLength" : "",
    "cSubProperty" : "",
    "cValue" : "",
    "cDisplaymessage" : "",
    "cInvalidMessage" : "",
    "cInvalidMessageFunc" : "",
}



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[secret > P > maxByteLength]<br/>Secret 컴포넌트에 입력 가능한 최대 Byte 수를 설정합니다.",
    "validation" : [
        "validate() 메소드로 유효성 체크 실행 시 다음과 같이 처리됩니다.",
        "입력값의 Byte 수가 설정값보다 크면 유효성 체크는 실패로 처리되고 displaymessage 속성에 따라 실패 메시지가 출력됩니다.",
        "시스템 기본 메시지는 'n byte를 초과하여 입력할 수 없습니다.' 이며, invalidMessage 또는 invalidMessageFunc 속성으로 메시지를 변경할 수 있습니다.",
        "minByteLength 또는 minlength 속성을 maxBytelength 값보다 크게 설정한 경우 유효성 체크는 항상 실패로 처리됩니다.",
        "maxByteLength 와 maxlength 를 모두 설정하면 설정값이 작은 속성이 적용됩니다. (같은 값이면 maxByteLength 적용)",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 정적 select1 기본값 설정 (gdl_boolean 은 코드값, 자체 값 selectbox 는 value)
    con_maxByteLength.setValue("5");
    con_subProperty.setSelectedIndex(0);
    con_value.setValue("secret");
    con_displaymessage.setValue("2");
    con_invalidMessageFunc.setSelectedIndex(0);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 컴포넌트 있으면 삭제
    if (typeof label1 !== 'undefined') {
        label1.remove();
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="입력값은 Target 재생성 시 스크립트로 설정하므로 maxByteLength 를 초과한 값도 만들어집니다. 병용 속성(maxlength, minlength, minByteLength) 을 판정하려면 입력값을 maxByteLength 이내로 낮춰야 합니다 (초과 값은 maxByteLength 가 먼저 걸림)\n입력값은 password 로 표시되어 화면에서 글자 수를 셀 수 없으므로 결과창의 길이와 Byte 수로 판정합니다"', '', 'label1');

    // 조건 설정
    scwin.gVar["cMaxByteLength"] = con_maxByteLength.getValue();
    scwin.gVar["cSubProperty"] = con_subProperty.getValue();
    scwin.gVar["cValue"] = con_value.getValue();
    scwin.gVar["cDisplaymessage"] = con_displaymessage.getText();
    scwin.gVar["cInvalidMessage"] = con_invalidMessage.getValue();
    scwin.gVar["cInvalidMessageFunc"] = con_invalidMessageFunc.getValue();

    let properties = {
        maxByteLength : scwin.gVar["cMaxByteLength"],
        displaymessage : scwin.gVar["cDisplaymessage"],
        invalidMessage : scwin.gVar["cInvalidMessage"],
        invalidMessageFunc : scwin.gVar["cInvalidMessageFunc"],
    }

    // maxByteLength 와 함께 설정할 속성 (선택한 1개만 적용)
    if (scwin.gVar["cSubProperty"] === "maxlength=3")
        properties.maxlength = "3";
    else if (scwin.gVar["cSubProperty"] === "maxlength=5")
        properties.maxlength = "5";
    else if (scwin.gVar["cSubProperty"] === "minlength=10")
        properties.minlength = "10";
    else if (scwin.gVar["cSubProperty"] === "minByteLength=10")
        properties.minByteLength = "10";

    let cList = $c.gcm.createCList(properties);

    // comp 생성 함수 호출 (헬퍼가 생성 직후 setValue 로 6자 초기값 secret 설정)
    await $c.gcm.createBasicSecret(cList);

    // 헬퍼 초기값을 선택한 입력값으로 덮음 (setValue 는 maxByteLength 로 잘리지 않아 초과 값도 설정 가능)
    target1.setValue(scwin.gVar["cValue"]);
}



// 미설정 표기 변환
scwin.fn_disp = function (strValue) {
    return (strValue === "") ? "미설정" : strValue;
}



// validate 실행 (maxByteLength 유효성 체크 발동 수단) - validation 1 ~ 5 판정 출력
scwin.btn_validate_onclick = function (e) {
    // password 는 화면으로 글자 수 확인이 불가하므로 판정 근거로 값 길이와 Byte 수를 함께 출력
    let strValue = target1.getValue() || "";
    let rtn = target1.validate();

    wf_body_bottom.getObj("scwin").setReturnValue("maxByteLength " + scwin.fn_disp(scwin.gVar["cMaxByteLength"]) + " / 병용 속성 " + scwin.fn_disp(scwin.gVar["cSubProperty"]) + " / displaymessage " + scwin.fn_disp(scwin.gVar["cDisplaymessage"]) + " / invalidMessage " + scwin.fn_disp(scwin.gVar["cInvalidMessage"]) + " / invalidMessageFunc " + scwin.fn_disp(scwin.gVar["cInvalidMessageFunc"]) + " / 입력값 " + strValue.length + "자 " + WebSquare.util.getStringByteSize(strValue) + "Byte -> validate() 반환값 : " + rtn);
}



// invalidMessageFunc 로 설정되는 사용자 정의 메시지 함수
scwin.fn_msg = function () {
    return "invalidMessageFunc 메시지 (원인 : " + this.getType() + ")";
}
